class Solution {
public:
    int maxProfit(vector<int>& prices, vector<int>& profits) {
        int n = prices.size();
        int m = *max_element(prices.begin(), prices.end()) + 1;
        vector<int> bit_left(m + 2, 0);
        auto update_left = [&](int idx, int val) {
            for (; idx < bit_left.size(); idx += idx & (-idx))
                bit_left[idx] = max(bit_left[idx], val);
        };
        auto query_left = [&](int idx) {
            int res = 0;
            for (; idx > 0; idx -= idx & (-idx))
                res = max(res, bit_left[idx]);
            return res;
        };
        vector<int> left_max(n, 0);
        for (int i = 0; i < n; i++) {
            left_max[i] = query_left(prices[i] - 1);
            update_left(prices[i], profits[i]);
        }
        vector<int> bit_right(m + 2, 0);
        auto update_right = [&](int idx, int val) {
            for (; idx > 0; idx -= idx & (-idx))
                bit_right[idx] = max(bit_right[idx], val);
        };
        auto query_right = [&](int idx) {
            int res = 0;
            for (; idx < bit_right.size(); idx += idx & (-idx))
                res = max(res, bit_right[idx]);
            return res;
        };
        vector<int> right_max(n, 0);
        for (int i = n - 1; i >= 0; i--) {
            right_max[i] = query_right(prices[i] + 1);
            update_right(prices[i], profits[i]);
        }
        int ans = -1;
        for (int j = 0; j < n; j++) {
            if (left_max[j] > 0 && right_max[j] > 0) {
                ans = max(ans, left_max[j] + profits[j] + right_max[j]);
            }
        }
        return ans;
    }
};

class Solution {
    public int maxProfit(int[] prices, int[] profits) {
        int n = prices.length;
        int m = 0;
        for (int p : prices) if (p > m) m = p;
        m += 1;
        int[] bitLeft = new int[m + 2];
        int[] leftMax = new int[n];
        for (int i = 0; i < n; i++) {
            int p = prices[i] - 1;
            int res = 0;
            for (int idx = p; idx > 0; idx -= idx & (-idx)) res = Math.max(res, bitLeft[idx]);
            leftMax[i] = res;
            for (int idx = prices[i]; idx < bitLeft.length; idx += idx & (-idx)) bitLeft[idx] = Math.max(bitLeft[idx], profits[i]);
        }
        int[] bitRight = new int[m + 2];
        int[] rightMax = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int p = prices[i] + 1;
            int res = 0;
            for (int idx = p; idx < bitRight.length; idx += idx & (-idx)) res = Math.max(res, bitRight[idx]);
            rightMax[i] = res;
            for (int idx = prices[i]; idx > 0; idx -= idx & (-idx)) bitRight[idx] = Math.max(bitRight[idx], profits[i]);
        }
        int ans = -1;
        for (int j = 0; j < n; j++) {
            if (leftMax[j] > 0 && rightMax[j] > 0) {
                int total = leftMax[j] + profits[j] + rightMax[j];
                if (total > ans) ans = total;
            }
        }
        return ans;
    }
}

