var maxProfit = function(prices, profits) {
    const n = prices.length;
    let m = 0;
    for (const p of prices) if (p > m) m = p;
    m += 1;
    const bitLeft = new Int32Array(m + 2);
    const leftMax = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        let res = 0;
        for (let idx = prices[i] - 1; idx > 0; idx -= idx & (-idx)) {
            if (bitLeft[idx] > res) res = bitLeft[idx];
        }
        leftMax[i] = res;
        for (let idx = prices[i]; idx < bitLeft.length; idx += idx & (-idx)) {
            if (profits[i] > bitLeft[idx]) bitLeft[idx] = profits[i];
        }
    }
    const bitRight = new Int32Array(m + 2);
    const rightMax = new Int32Array(n);
    for (let i = n - 1; i >= 0; i--) {
        let res = 0;
        for (let idx = prices[i] + 1; idx < bitRight.length; idx += idx & (-idx)) {
            if (bitRight[idx] > res) res = bitRight[idx];
        }
        rightMax[i] = res;
        for (let idx = prices[i]; idx > 0; idx -= idx & (-idx)) {
            if (profits[i] > bitRight[idx]) bitRight[idx] = profits[i];
        }
    }
    let ans = -1;
    for (let j = 0; j < n; j++) {
        if (leftMax[j] > 0 && rightMax[j] > 0) {
            const total = leftMax[j] + profits[j] + rightMax[j];
            if (total > ans) ans = total;
        }
    }
    return ans;
};
